#include <vector>

using namespace std;

class Solution {
public:
    vector<long long> resultArray(vector<int>& nums, int k) {
        vector<long long> ans(k, 0);
        vector<long long> dp(k, 0);
        for (int num : nums) {
            vector<long long> newDp(k, 0);
            int numMod = num % k;
            newDp[numMod]++;
            for (int i = 0; i < k; ++i) {
                if (dp[i]) {
                    int newMod = ((long long)i * numMod) % k;
                    newDp[newMod] += dp[i];
                }
            }
            for (int i = 0; i < k; ++i) {
                ans[i] += newDp[i];
            }
            dp = std::move(newDp);
        }
        return ans;
    }
};

